
import base64
import gzip
import xml.dom.minidom

# Conteúdo dpsXmlGZipB64 recebido da API Nacional
conteudo = """"""

try:
    # 1. Decodifica Base64
    arquivo_gzip = base64.b64decode(conteudo.strip(), validate=True)

    # 2. Descompacta GZIP
    xml_bytes = gzip.decompress(arquivo_gzip)

    # 3. Formata XML
    documento = xml.dom.minidom.parseString(xml_bytes)
    xml_formatado = documento.toprettyxml(
        indent="    ",
        encoding="utf-8"
    )

    # 4. Salva arquivo
    with open("dps.xml", "wb") as arquivo:
        arquivo.write(xml_formatado)

    print("DPS descompactada com sucesso!")
    print("Arquivo gerado: dps.xml")

except Exception as erro:
    print(f"Erro ao processar DPS: {erro}")
